import React, {
  useCallback,
  useRef,
  useState,
  type ComponentRef,
  type ComponentType,
  type ReactNode,
} from 'react';
import {
  Pressable,
  StyleSheet,
  Text,
  useWindowDimensions,
  View,
  type StyleProp,
  type ViewStyle,
} from 'react-native';

import { FileViewIcon } from './FileViewIcon';
import { fileViewChoices, viewMenuPlace, type FileViewMode, type ViewMenuAnchor } from './fileViewLogic';

/**
 * One button that chooses how the files are shown. It shows the view in use; a press drops a
 * short list of the views under it, and a press on one chooses it. Use it where a toolbar has
 * better things to do with its width than three buttons (`ViewSwitcher` is the three).
 *
 * The list has to sit over everything else on the screen, so it opens in a pop-up window that
 * covers the screen: the app passes its own as `cover` (react-native's `Modal` fits as it is).
 * Without one the list is drawn in place under the button, which is enough where nothing that
 * comes later on the page is drawn over it.
 */

/** A pop-up window that covers the screen. react-native's `Modal` is one. */
export type ViewMenuCover = ComponentType<{
  visible?: boolean;
  transparent?: boolean;
  animationType?: 'none' | 'slide' | 'fade';
  statusBarTranslucent?: boolean;
  onRequestClose?: () => void;
  children?: ReactNode;
}>;

export type ViewMenuProps = {
  value: FileViewMode;
  onChange: (mode: FileViewMode) => void;
  /** The views this app offers. All of them when left out. */
  modes?: readonly FileViewMode[];
  /** The app's pop-up window, for the list to open in. */
  cover?: ViewMenuCover;
  /** The height of the button. */
  size?: number;
  /** Icons and words. */
  color?: string;
  /** The small arrow on the button, and a view that is not the chosen one. */
  quiet?: string;
  /** The chosen view in the list. */
  accent?: string;
  /** Behind the button. */
  track?: string;
  /** Behind the list. */
  surface?: string;
  /**
   * A solid colour painted under `surface`, for an app whose surface colour is see-through (a
   * white wash over its background, say). Without it a see-through surface lets the page behind
   * the list show through the list.
   */
  base?: string;
  /** The edge of the list. */
  line?: string;
  /** The button's own shape, to match the buttons beside it. */
  style?: StyleProp<ViewStyle>;
};

const LIST_WIDTH = 168;
const LINE_HEIGHT = 42;
const LIST_PADDING = 5;

export function ViewMenu({
  value,
  onChange,
  modes,
  cover: Cover,
  size = 38,
  color = '#fff',
  quiet = 'rgba(255,255,255,0.62)',
  accent = '#fff',
  track = 'rgba(255,255,255,0.10)',
  surface = 'rgb(28,28,30)',
  base,
  line = 'rgba(255,255,255,0.18)',
  style,
}: ViewMenuProps) {
  const choices = fileViewChoices(modes);
  const current = choices.find((choice) => choice.value === value) ?? choices[0];
  const button = useRef<ComponentRef<typeof View>>(null);
  const [anchor, setAnchor] = useState<ViewMenuAnchor | null>(null);
  const screen = useWindowDimensions();
  const close = useCallback(() => setAnchor(null), []);

  if (!current) return null;
  const open = anchor !== null;

  const press = () => {
    if (open) return close();
    if (!Cover || !button.current) return setAnchor({ x: 0, y: 0, width: 0, height: size });
    // Where the button is on the screen, so the list can be put under it inside the pop-up window.
    button.current.measureInWindow((x, y, width, height) => setAnchor({ x, y, width, height }));
  };

  const list = (
    <View
      style={[styles.list, { backgroundColor: base ?? surface, borderColor: line }]}
      accessibilityRole="menu"
      // A press between two lines belongs to the list, not to whatever is behind it.
      onStartShouldSetResponder={() => true}
    >
      {base ? <View style={[styles.wash, { backgroundColor: surface }]} pointerEvents="none" /> : null}
      {choices.map((choice) => {
        const chosen = choice.value === value;
        return (
          <Pressable
            key={choice.value}
            // The edge colour doubles as the pressed colour, so it shows on a light list as well as a dark one.
            style={({ pressed }) => [styles.line, pressed && { backgroundColor: line }]}
            onPress={() => {
              close();
              if (!chosen) onChange(choice.value);
            }}
            accessibilityRole="menuitem"
            accessibilityLabel={choice.label}
            accessibilityState={{ selected: chosen }}
          >
            <FileViewIcon name={choice.icon} size={18} color={chosen ? accent : quiet} />
            <Text style={[styles.name, { color: chosen ? accent : color }]} numberOfLines={1}>
              {choice.name}
            </Text>
            {chosen ? <FileViewIcon name="tick" size={15} color={accent} /> : null}
          </Pressable>
        );
      })}
    </View>
  );

  const place = anchor ? viewMenuPlace(anchor, screen.width, LIST_WIDTH) : null;

  return (
    <View style={styles.wrap}>
      <Pressable
        ref={button}
        style={[
          styles.button,
          { height: size, borderRadius: Math.round(size * 0.27), backgroundColor: track },
          style,
        ]}
        onPress={press}
        accessibilityRole="button"
        accessibilityLabel={`${current.label}. Change view`}
        accessibilityState={{ expanded: open }}
        hitSlop={4}
      >
        <FileViewIcon name={current.icon} size={Math.round(size * 0.47)} color={color} />
        <FileViewIcon name="caret" size={Math.round(size * 0.29)} color={quiet} />
      </Pressable>

      {Cover ? (
        <Cover visible={open} transparent animationType="fade" statusBarTranslucent onRequestClose={close}>
          <Pressable
            style={styles.cover}
            onPress={close}
            accessibilityRole="button"
            accessibilityLabel="Close view list"
          />
          {place ? <View style={[styles.placed, place]}>{list}</View> : null}
        </Cover>
      ) : open ? (
        <View style={[styles.inPlace, { top: size + 6 }]}>{list}</View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { zIndex: 30 },
  button: {
    minWidth: 44,
    paddingHorizontal: 9,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 3,
  },
  cover: { position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 },
  placed: { position: 'absolute', width: LIST_WIDTH },
  inPlace: { position: 'absolute', right: 0, width: LIST_WIDTH, zIndex: 30 },
  list: {
    borderRadius: 14,
    borderWidth: StyleSheet.hairlineWidth * 2,
    paddingVertical: LIST_PADDING,
    overflow: 'hidden',
    shadowColor: '#000',
    shadowOpacity: 0.35,
    shadowRadius: 14,
    shadowOffset: { width: 0, height: 6 },
    elevation: 12,
  },
  wash: { position: 'absolute', top: 0, right: 0, bottom: 0, left: 0 },
  line: { height: LINE_HEIGHT, paddingHorizontal: 13, flexDirection: 'row', alignItems: 'center', gap: 11 },
  name: { flex: 1, fontSize: 15, fontWeight: '600' },
});
